/** Weights for the 8 serial digits of a UPU S10 number (see docs/carriers.md). */
const S10_WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** Check digit for the 8-digit S10 serial number. */
export function s10CheckDigit(serial: string): number {
  const sum = S10_WEIGHTS.reduce((acc, weight, i) => acc + weight * Number(serial[i]), 0);
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

/** UPU S10 number of Austrian Post: 2 letters, 8 digits, check digit, `AT`. Expects upper case. */
export function isValidAtpTrackingNumber(value: string): boolean {
  const match = /^[A-Z]{2}(\d{8})(\d)AT$/.exec(value);
  return match !== null && s10CheckDigit(match[1]!) === Number(match[2]);
}
